          if (Math.abs(d[axis]) < 1e-6) continue;
          let t = (value - o[axis]) / d[axis],
            k = 1 - axis,
            p = [o[0] + d[0] * t, o[1] + d[1] * t];
          if (
            t > 0.001 &&
            t < tmax &&
            p[k] >= r[k] - 0.0001 &&
            p[k] <= r[k] + r[k + 2] + 0.0001
